class Solution:
    def leastOpsExpressTarget(self, x: int, target: int) -> int:
        operators = {'*': 1, '/': 1, '+': 2, '-': 2}
        result = target // x
        for op in operators:
            result = result * x + target % x
        return len(operators) - len(str(result))
